import io
import unittest
from contextlib import redirect_stderr, redirect_stdout

from textkit.cli import main
from textkit.roman import from_roman, to_roman


class RomanTests(unittest.TestCase):
    def test_known(self):
        for n, s in [(1, "I"), (4, "IV"), (1994, "MCMXCIV"), (3999, "MMMCMXCIX")]:
            self.assertEqual(to_roman(n), s)
            self.assertEqual(from_roman(s), n)

    def test_round_trip(self):
        for n in range(1, 4000):
            self.assertEqual(from_roman(to_roman(n)), n)

    def test_to_invalid(self):
        for n in [0, 4000, -1]:
            with self.assertRaises(ValueError, msg=n):
                to_roman(n)

    def test_from_invalid(self):
        for s in ["IIII", "IC", "VX", "mcm", "", "MMMM", "IIX", "XM", "A", " I"]:
            with self.assertRaises(ValueError, msg=s):
                from_roman(s)


class CliTests(unittest.TestCase):
    def run_cli(self, *argv):
        out, err = io.StringIO(), io.StringIO()
        with redirect_stdout(out), redirect_stderr(err):
            code = main(list(argv))
        return code, out.getvalue(), err.getvalue()

    def test_to(self):
        self.assertEqual(self.run_cli("roman", "1994"), (0, "MCMXCIV\n", ""))

    def test_from(self):
        self.assertEqual(self.run_cli("roman", "MCMXCIV"), (0, "1994\n", ""))

    def test_invalid(self):
        for v in ["IIII", "0", "4000"]:
            code, out, err = self.run_cli("roman", v)
            self.assertEqual(code, 2)
            self.assertTrue(err.startswith("error:"))


if __name__ == "__main__":
    unittest.main()
